'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
const positions = Array.from({ length: n + 1 }, () => []);

for (let i = 0; i < n; i++) {
  positions[input[i + 1]].push(i);
}

let answer = 1;

for (let a = 1; a <= n; a++) {
  for (let b = a + 1; b <= n; b++) {
    const pa = positions[a];
    const pb = positions[b];
    let i = 0;
    let j = 0;
    let runs = 0;
    let previous = 0;

    while (i < pa.length || j < pb.length) {
      let value;

      if (j >= pb.length || (i < pa.length && pa[i] < pb[j])) {
        value = a;
        i++;
      } else {
        value = b;
        j++;
      }

      if (value !== previous) {
        runs++;
        previous = value;
      }
    }

    if (runs > answer) answer = runs;
  }
}

console.log(answer.toString());
